import pexpect
from taf.internal.execution.base import ProcessFactory
from .local_pty_process import LocalPtyProcess, \
    LocalPtyInputStream, LocalPtyOutputStream, LocalPtyErrorStream


class LocalPtyProcessFactory(ProcessFactory):
    def create_process(self, command):
        pty_process = self._create_pty_process(command)
        stdin = self._create_local_pty_input_stream(pty_process=pty_process)
        stdout = self._create_local_pty_output_stream(
            pty_process=pty_process)
        stderr = self._create_local_pty_error_stream(pty_process=pty_process)
        return LocalPtyProcess(
            command=command,
            stdin=stdin,
            stdout=stdout,
            stderr=stderr,
            pty_process=pty_process)

    def _create_pty_process(self, command):
        pty_process = pexpect.spawn(
            command="/bin/bash",
            args=[
                "-c",
                command.decode("cp437")],
            echo=True,
            use_poll=True,
            maxread=1,
            encoding="cp437",
        )
        return pty_process

    def _create_local_pty_input_stream(self, pty_process):
        return LocalPtyInputStream(pty_process=pty_process)

    def _create_local_pty_output_stream(self, pty_process):
        return LocalPtyOutputStream(
            pty_process=pty_process)

    def _create_local_pty_error_stream(self, pty_process):
        return LocalPtyErrorStream(pty_process=pty_process)
